// Model family catalog used by the /models page.
// Add a new family by appending an entry here — no page edits needed.
// Models that match no explicit family are grouped by vendor (see vendorKey);
// only IDs with neither an org prefix nor a known vendor token land in "Other".

export interface ModelFamily {
  id: string;
  name: string;
  category: string;
  description: string;
  tags?: string[];
  match: (modelId: string) => boolean;
  // True for cards generated by the vendor fallback rather than listed below.
  auto?: boolean;
}

