const titleCase = (key: string) =>
  key.split(/[-_.\s]+/).filter(Boolean).map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

/**
 * Vendor key for a model ID that no explicit family matched: a known vendor token
 * at the start of the model name ("deepseek-v9-pro" -> "deepseek"), else the org
 * prefix before "/" ("acme/foo-1" -> "acme"), else null (truly unclassifiable).
 */
export function vendorKey(modelId: string): string | null {
  const id = modelId.trim().toLowerCase().replace(/:[a-z0-9._-]+$/, '');
  const slash = id.indexOf('/');
  const name = slash >= 0 ? id.slice(slash + 1) : id;
  for (const token of TOKENS_LONGEST_FIRST) {
    if (name.startsWith(token) && !/[a-z]/.test(name.charAt(token.length))) return VENDOR_TOKENS[token];
  }
  if (slash > 0) {
    const org = id.slice(0, slash).replace(/[^a-z0-9._-]/g, '');
    if (org) return ORG_ALIASES[org] ?? org;
  }
  return null;
}

export function vendorFamily(key: string): ModelFamily {
  const display = VENDOR_DISPLAY[key];
  const name = display?.name ?? titleCase(key);
  return {
    id: `vendor-${key}`,
    name,
    category: display?.category ?? name,
    description: `Other ${name} models`,
    auto: true,
    match: id => vendorKey(id) === key,
  };
}

// ── Classification ─────────────────────────────────────────────────────────
export interface ClassifiableModel {
  id: string;
  status?: string | null;
}
export interface ClassifiableProvider {
  id: string;
  status?: string;
  models: readonly ClassifiableModel[];
}
export interface ProviderModels<P extends ClassifiableProvider> {
  provider: P;
  models: P['models'][number][];
}
export interface ModelClassification<P extends ClassifiableProvider> {
  // Explicit families first (in MODEL_FAMILIES order), then vendor fallback cards
  // sorted by name. Families with no models are omitted.
  families: { family: ModelFamily; entries: ProviderModels<P>[] }[];
  other: ProviderModels<P>[];
}

// Non-chat models (e.g. safety classifiers like llama-prompt-guard) and deprecated ones are hidden.
export function isListableModel(model: ClassifiableModel): boolean {
  return model.status !== 'deprecated' && !/prompt[-_]?guard/i.test(model.id);
}

/**
 * Groups the listable models of active providers into families. A model may sit in
 * several explicit families when their matchers overlap; the vendor fallback only
 * sees models no explicit family claimed, and "Other" only those without a vendor key.
 */
export function classifyModels<P extends ClassifiableProvider>(
  providers: readonly P[],
  families: readonly ModelFamily[] = MODEL_FAMILIES,
): ModelClassification<P> {
  type M = P['models'][number];
  const active = providers
    .filter(p => p.status === 'active')
    .map(provider => ({ provider, models: (provider.models as readonly M[]).filter(isListableModel) }));

  const groups = (family: ModelFamily, pick: (p: P, m: M) => boolean) => {
    const entries: ProviderModels<P>[] = [];
    for (const { provider, models } of active) {
      const matching = models.filter(m => pick(provider, m));
      if (matching.length > 0) entries.push({ provider, models: matching });
    }
    return entries.length > 0 ? { family, entries } : null;
  };

  const claimed = new Set<string>();
  const result: ModelClassification<P> = { families: [], other: [] };
  for (const family of families) {
    const card = groups(family, (_p, m) => family.match(m.id));
    if (!card) continue;
    for (const { provider, models } of card.entries) for (const m of models) claimed.add(`${provider.id}:${m.id}`);
    result.families.push(card);
  }

  const unclaimed = (p: P, m: M) => !claimed.has(`${p.id}:${m.id}`);
  const vendorKeys = new Set<string>();
  for (const { provider, models } of active) {
    for (const m of models) {
      if (!unclaimed(provider, m)) continue;
      const key = vendorKey(m.id);
      if (key) vendorKeys.add(key);
    }
  }
  const autoCards = [...vendorKeys]
    .map(key => groups(vendorFamily(key), (p, m) => unclaimed(p, m) && vendorKey(m.id) === key))
    .filter(card => card !== null)
    .sort((a, b) => a.family.name.localeCompare(b.family.name) || a.family.id.localeCompare(b.family.id));
  result.families.push(...autoCards);

  for (const { provider, models } of active) {
    const rest = models.filter(m => unclaimed(provider, m) && vendorKey(m.id) === null);
    if (rest.length > 0) result.other.push({ provider, models: rest });
  }
  return result;
}

